-- Migration: Replace static photo exercises with 1,500 pure animated GIF exercises from ExerciseDB
-- Ensures 100% of exercises in public.exercises have high-definition animated .gif demonstrations.

-- 1. Remove old static photo exercises
DELETE FROM public.exercises WHERE id LIKE 'cat_ex_%' AND id != 'cat_ex_seated_leg_press';

-- 2. Insert 1,500 animated GIF exercises
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  type = EXCLUDED.type,
  target_sets = EXCLUDED.target_sets,
  target_rep_min = EXCLUDED.target_rep_min,
  target_rep_max = EXCLUDED.target_rep_max,
  category = EXCLUDED.category,
  image_url = EXCLUDED.image_url,
  is_custom = false;
